// Builds the SQL twin of riskCheck (core/text-checks.js, BR-MSG-008) and its pgTAP parity test, so the
// trigger that sets messages.risk_flag and the web read the same word list (engineering-constitution.md §7).
//   node tests/fixtures/risk-sql.js function   prints the risk_check function for a new migration
//   node tests/fixtures/risk-sql.js parity     prints supabase/tests/database/12_risk_parity.sql
// tests/unit/risk-parity.test.js fails if the latest migration or the parity test is out of date.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { RISK_PHRASES } from '../../core/text-checks.js';

export const PARITY_TEST_PATH = 'supabase/tests/database/12_risk_parity.sql';
const q = (v) => `'${String(v).replaceAll("'", "''")}'`;

export function riskCheckSql() {
  const all = Object.values(RISK_PHRASES).flat();
  const phrases = all.filter((p) => typeof p === 'string');
  const patterns = all.filter((p) => p instanceof RegExp).map((p) => p.source);
  return [
    '-- GENERATED by tests/fixtures/risk-sql.js from RISK_PHRASES in core/text-checks.js. Do not edit by hand.',
    '-- BR-MSG-008: the same normalized text and the same list as riskCheck.',
    'create or replace function public.risk_check(p_text text)',
    'returns boolean',
    'language sql',
    'stable',
    'set search_path = public, extensions',
    'as $$',
    '  with h as (',
    "    select ' ' || btrim(regexp_replace(replace(replace(lower(extensions.unaccent(coalesce(p_text, ''))), '’', ''), '''', ''),",
    "      '[^a-z0-9$]+', ' ', 'g')) || ' ' as t",
    '  )',
    '  select exists (',
    `    select 1 from h, unnest(array[${phrases.map(q).join(', ')}]::text[]) p`,
    "    where h.t like '% ' || p || ' %'",
    '  ) or exists (',
    `    select 1 from h, unnest(array[${patterns.map(q).join(', ')}]::text[]) r`,
    '    where h.t ~ r',
    '  )',
    '$$;',
  ].join('\n');
}

export function riskParityPgtap(fixture) {
  const lines = [
    '-- GENERATED by tests/fixtures/risk-sql.js from tests/fixtures/text-checks.json. Do not edit.',
    '-- Parity: risk_check (SQL) answers the same as riskCheck in core/text-checks.js (BR-MSG-008).',
    'begin;',
    'create extension if not exists pgtap with schema extensions;',
    `select plan(${fixture.cases.length});`,
    '',
  ];
  for (const c of fixture.cases) {
    lines.push(`select is(public.risk_check(${q(c.text)}), ${c.risk}, ${q(`AC-033-3 ${c.text}`)});`);
  }
  lines.push('', 'select * from finish();', 'rollback;', '');
  return lines.join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const what = process.argv[2];
  if (what === 'function') process.stdout.write(`${riskCheckSql()}\n`);
  else if (what === 'parity') {
    const fixture = JSON.parse(readFileSync(new URL('./text-checks.json', import.meta.url), 'utf8'));
    process.stdout.write(riskParityPgtap(fixture));
  } else {
    console.error('usage: node tests/fixtures/risk-sql.js function|parity');
    process.exit(1);
  }
}
